import {Database} from 'bun:sqlite';
const db=new Database('/private/tmp/e2e-1794804125288-e8ffa028.sqlite',{readonly:true});
const result='/private/tmp/worker-sqlite-corrections.DuGPio/full-sqlite.json';
const log='/private/tmp/worker-sqlite-corrections.DuGPio/full-sqlite.log';
let prior='';
try {
 while(!(await Bun.file(result).exists())) {
  const rows=db.query("SELECT w.name,r.id,r.status,s.nodeId,s.status AS stepStatus FROM workflow_runs r JOIN workflows w ON w.id=r.workflowId LEFT JOIN workflow_run_steps s ON s.runId=r.id WHERE r.status='running' OR s.status='running'").all();
  const current=JSON.stringify(rows);
  if(current!==prior){
   const lastScenario=(await Bun.file(log).text()).split('\n').filter(line=>line.startsWith('PASS ')).at(-1);
   console.log(JSON.stringify({timeBCN:new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Madrid',dateStyle:'short',timeStyle:'medium'}).format(new Date())+' BCN',lastScenario,rows}));
   prior=current;
  }
  await Bun.sleep(50);
 }
}finally{db.close();}
